"""Render expanded procurement content using captured specifications and focused profiles."""
import importlib.util
editorial_spec=importlib.util.spec_from_file_location('packhub_expanded',ROOT/'content/expanded.py')
expanded_content=importlib.util.module_from_spec(editorial_spec);editorial_spec.loader.exec_module(expanded_content)

def prose_section(id,title,text):
 return '<section id="'+id+'"><h2>'+esc(title)+'</h2><p>'+esc(text)+'</p></section>'

def question_list(items):
 return '<div class="faq">'+''.join('<details><summary>'+esc(q)+'</summary><p>'+esc(a)+'</p></details>' for q,a in items)+'</div>'

def product_profile(record):
 groups=set(record['groups'])
 if '953304411' in groups:return 'display'
 if '803759676' in groups:return 'label'
 if groups&{'807897313','952983140'}:return 'print'
 name=record['name'].lower()
 if 'display' in name:return 'display'
 if any(s in name for s in ['sticker','label']):return 'label'
 if any(s in name for s in ['card','tag','booklet']) and 'box' not in name:return 'print'
 if 'pouch' in record['detail']['title'].lower() and '919632767' in record['groups']:return 'pouch'
 if 'bag' in name:
  return 'bag' if 'paper' in name or 'kraft' in name else 'poly'
 if any(s in name for s in ['magnetic','drawer','lid & base','gift box','tube']):return 'rigid'
 if any(s in name for s in ['mailer','shipping','corrugated']):return 'mailer'
 return 'carton'

def product_editorial(record,rows):
 profile=product_profile(record);name=record['name'];reference=record['reference']
 material=next((v for k,v in rows if k=='Material'),'a material selected for your product')
 size=next((v for k,v in rows if k=='Size'),'custom dimensions to be agreed')
 printing=next((v for k,v in rows if k=='Printing'),'custom artwork and printing for specification review')
 body='<section class="section softbg"><div class="wrap tank-layout"><nav class="tank-nav" aria-label="On this product page"><h2>Plan your packaging</h2>'+''.join('<a href="#'+id+'">'+title+'</a>' for id,title in [('reference-specification','This reference'),('product-design','Structure & use'),('customization','Customization'),('sample-review','Samples & quality'),('order-planning','Order planning'),('product-questions','Product FAQ')])+'</nav><article class="tank-content">'
 body+=prose_section('reference-specification','A closer look at '+name.lower(),f'{reference} is the product reference to include when you contact PackHubGlobe. The captured material description is {material}; the listed size direction is {size}. Printing information for this reference includes {printing}. Use these details to start a specification, then identify any changes needed for your product. The image shows a packaging design direction rather than a fixed stock item, and the finished order should be defined by its agreed artwork, construction and sample. Custom orders start at 500 pieces.')
 for i,(title,text) in enumerate(expanded_content.PROFILES[profile]):
  body+=prose_section('product-design' if i==0 else 'design-'+str(i),title,text)
 body+=prose_section('customization','Customize the package as a complete system','Bring the contents, package and printed information into one brief. Tell us which reference features you want to retain and which you want to change: dimensions, material, closure, insert, color, printed panels or finishing. Supply a logo and describe the artwork status, even if the design is still being developed. Structural decisions should be resolved before important text is positioned on a final dieline. If several components need to coordinate, list their individual quantities and explain how they fit together at packing and delivery.')
 body+='<h3>Your specification checklist</h3><ul><li>Reference '+reference+' and the product or complete set being packed.</li><li>Finished dimensions or fill quantity, measurement units and orientation.</li><li>Quantity per size and artwork version, starting from 500 pieces.</li><li>Material, printing, finish and functional features to review.</li><li>Artwork files, sample priorities, destination and target arrival window.</li></ul>'
 body+=prose_section('sample-review','Plan the sample and quality checks','Choose the sample according to the decisions still open. A structural sample helps review size, assembly and product access. A printed reference helps review artwork and selected appearance questions; confirm how closely its material and print route represent the order. Agree the important cosmetic and functional checks before production. Inspect the package with its intended contents and record the approved revision. A change to the product, material, closure or insert may require the relevant decision to be reviewed again rather than carried over automatically.')
 body+=prose_section('order-planning','MOQ, quotation and delivery planning','The minimum order quantity for this catalog reference is 500 pieces. State the quantity for each size and printed design so the quotation can identify the proposed production split. Ask for tooling or setup, sampling, product supply, export packing and freight to be explained where applicable. Production scheduling follows the agreed specification and approvals; delivery also depends on the destination and shipping arrangement. Include your required arrival window in the first message, and keep any change to artwork, quantity or packing visible when comparing a revised quotation.')
 faq_items=[('What is the MOQ for '+reference+'?','The minimum order quantity is 500 pieces. Tell us how that quantity is divided across sizes and artwork versions, and request the production split in your written quotation.'),('Can I add my own logo and custom dimensions?','Yes. Send the reference, product measurements, logo and artwork status. The dimensions, printable areas and finishing options are reviewed together before the final specification and sample are approved.'),('Which material and printing options belong to this reference?',f'The recorded material is {material}. Printing is listed as {printing}. These are the reference details to discuss; identify any requested changes and confirm the final construction and appearance in the order specification.'),('What should I send for an accurate quote?','Include the product or filled contents, dimensions with units, quantity per design, print and finishing requirements, sample priorities, delivery country and target arrival window. Add '+reference+' so we can identify the image and captured details.'),('Can the image alone be used as a production approval?','Use the image to communicate a direction. Physical fit, printed color, finishing, sealing or transport behavior need the appropriate specification and sample checks for the actual application.'),('How do I place a repeat order?','Share the previous reference and approved artwork revision, then confirm whether the contents, material, size, printed information or delivery arrangement has changed. Review affected sample or quality checks before repeating production.')]
 body+='<section id="product-questions"><h2>'+esc(name)+' questions</h2>'+question_list(faq_items)+'</section><section><h2>Useful buying guides</h2><p>Prepare a <a href="/guides/packaging-quote-checklist/">complete packaging quote brief</a>, choose the right <a href="/guides/packaging-sample-types/">sample type</a>, and understand what a <a href="/guides/packaging-print-proof/">print proof should approve</a>. For related materials, explore <a href="/materials/">materials and finishes</a>.</p></section></article></div></section>'
 return body

def guide_extra(slug):
 data=expanded_content.GUIDE_EXPANSIONS[slug]
 body='<div class="guide-answer"><strong>Quick answer</strong><p>'+esc(data['answer'])+'</p></div>'
 body+=prose_section('worked-example','A worked procurement example',data['example'])
 body+='<h2 id="comparison">Compare the decisions that matter</h2>'+table(data['rows'])
 body+='<section id="common-mistakes"><h2>Common mistakes to avoid</h2><ul>'+''.join('<li>'+esc(s)+'</li>' for s in data['mistakes'])+'</ul><p>Use the comparison above to identify what is still unknown. Ask for a written answer or a suitable sample where a purchasing decision depends on that point. An unanswered requirement is easier to resolve before artwork, tooling or a production quantity is approved than after the order has been scheduled.</p></section>'
 body+='<section id="approval-checklist"><h2>Your approval checklist</h2><ul>'+''.join('<li>'+esc(s)+'</li>' for s in data['checks'])+'</ul><p>Keep this checklist with the specification and the people responsible for product, artwork and purchasing approval. Give each file and sample a clear revision. If an item remains open, identify who will answer it and which part of the order depends on the answer. This makes the approval useful to the next person reviewing the package, rather than leaving important decisions in an email thread or a photograph without context.</p></section>'
 body+=prose_section('approval-record','Turn the findings into a clear approval record','Record the reference reviewed, the conditions or contents used, the findings and the changes requested. Distinguish a design direction from an approved production specification. When several people are involved, identify who approves wording, structure, printed appearance and the commercial terms. Keep the final artwork and the relevant physical reference together. If a later revision changes one decision, review the affected parts explicitly rather than silently treating every earlier approval as valid for the new version.')
 body+='<section id="guide-faq"><h2>Frequently asked questions</h2>'+question_list(data['faq'])+'</section><h2>Apply this to your packaging project</h2><p>Use <a href="/guides/packaging-quote-checklist/">the quote checklist</a> to assemble your brief, then explore <a href="'+data['links'][0]+'">relevant packaging options</a> or discuss <a href="'+data['links'][1]+'">the related specification decision</a>. Start with what you know and label the points you want us to help resolve.</p>'
 sources=[('Adobe: print color management','https://helpx.adobe.com/illustrator/using/printing-color-management.html'),('ISTA: selecting package test procedures','https://www.ista.org/test_procedures.php')]
 if slug in ['internal-vs-external-box-dimensions','paper-bag-load-testing','label-roll-direction']:sources=[('GS1: package measurement standard','https://www.gs1.org/standards/gs1-package-and-product-measurement-standard/current-standard'),('ISTA: reviewing changed packaged products','https://support.ista.org/portal/en/kb/articles/when-should-a-packaged-product-be-retested')]
 if slug=='label-roll-direction':sources[1]=('GS1: code placement on retail packaging','https://ref.gs1.org/guidelines/2d-in-retail/')
 if slug in ['mailer-boxes-vs-shipping-boxes','folding-cartons-vs-rigid-boxes']:sources[0]=('FEFCO: corrugated design style references','https://www.fefco.org/technical-information/fefco-code')
 body+='<section class="article-note"><h2>Technical references and further reading</h2><p>These references explain relevant measurement, print or test-planning concepts. They do not certify the products shown on this website.</p><ul>'+''.join('<li><a href="'+url+'" target="_blank" rel="noopener noreferrer">'+esc(title)+'</a></li>' for title,url in sources)+'</ul></section>'
 return body

def home_family_cards():
 body='<section class="section softbg" id="packaging"><div class="wrap"><div class="sectionhead centered"><h2>Choose your packaging family.</h2><p>Start with the structure, then compare a reference and make the details your own.</p></div><div class="resourcegrid">'
 for title,path,text in [('Paper boxes','paper-boxes','Explore folding cartons, corrugated mailers, rigid gift boxes, magnetic boxes and drawer structures. Compare the opening experience, usable space and product protection around the way you sell and ship.'),('Bags & pouches','bags','Find paper shopping bags, paper mailing bags, garment bags, poly mailers and printed pouches. Begin with the contents, carrying or filling workflow, closure and the surface your customer will handle.'),('Packaging accessories','packaging-accessories','Complete the pack with cards, hang tags, labels, stickers and display accessories. Coordinate the graphic identity while choosing the paper, attachment or adhesive for the actual application.')]:
  body+='<article class="guidecard"><h3><a href="/catalog/'+path+'/">'+title+'</a></h3><p>'+text+'</p><a class="textlink" href="/catalog/'+path+'/">Explore '+title.lower()+' ↗</a></article>'
 return body+'</div></div></section>'

def expanded_home():
 body='<section class="section wrap"><div class="sectionhead"><div><h2>Custom printed packaging, specified for your product.</h2><p>A good packaging project connects product fit, printed branding and the way the finished order is handled.</p></div></div><div class="two"><section><h3>Start with the complete contents</h3><p>Share the product, dimensions or fill quantity, accessories and any existing retail pack. A carton around a bottle, a presentation box around a set and a mailer around the whole order create different requirements. Tell us how the package will be displayed, filled, carried or shipped so the structure can be reviewed around its real job.</p><p>Our catalog provides images and reference specifications for 856 packaging products. Use a PHG reference to identify a direction, then explain the changes you need. This keeps the conversation tied to a specific example while leaving room to resolve dimensions, materials, closure and artwork for your brand.</p></section><section><h3>Plan print and material together</h3><p>Paperboard, kraft paper, rigid wraps, films and label materials interact differently with print and finishing. Identify your important logo colors and the surfaces customers will see. Discuss foil, embossing, coating or clear-film white ink where relevant to the selected reference rather than assuming the same instructions suit every material.</p><p>Review the right sample for each decision. A structural sample can answer fit and assembly questions, while a suitable printed reference helps with artwork and appearance. Keep approvals attached to the material, dieline and artwork revision that will actually be used.</p></section></div></section><section class="section softbg"><div class="wrap split"><div><span class="eyebrow">Orders from 500 pieces</span><h2>A clearer brief. A more useful quotation.</h2><p>Custom catalog products start at 500 pieces. List quantities by product, size and printed design, especially when your project includes several components. Identify the delivery country, sample priorities and target arrival window so your request can be reviewed as a complete order.</p><p>Compare quotations using the same specification. Ask which costs relate to setup, samples, production, export packing and freight where applicable. Price and timing are confirmed for the agreed order; a catalog photograph is the starting point for the conversation.</p><a class="textlink" href="/guides/packaging-quote-checklist/">Build a better packaging brief ↗</a></div><div><h3>Information to send with your enquiry</h3><ul class="home-checklist"><li>Product reference or the packaging format you need.</li><li>Product measurements, fill quantity or a sample to review.</li><li>Quantity per size and artwork version, from 500 pieces.</li><li>Material, closure, insert and finishing priorities.</li><li>Artwork status, sample needs and delivery destination.</li></ul><a class="button" href="/request-quote/">Discuss your packaging project</a></div></div></section>'
 return body
